// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.datastore;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.File;
import java.io.IOException;
import java.io.RandomAccessFile;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class DataStorePresenceTest {

	@TempDir
	File directory;

	@Test
	void checksPresentAndAbsentIdsWithoutMaterializingValues() throws Exception {
		try (DataStore store = new DataStore(directory, "values")) {
			int id = store.storeData(new byte[] { 1, 2, 3 });
			assertThat(store.hasData(id)).isTrue();
			assertThat(store.hasData(0)).isFalse();
			assertThat(store.hasData(-1)).isFalse();
			assertThat(store.hasData(id + 1)).isFalse();
			assertThat(store.hasData(Integer.MAX_VALUE)).isFalse();
		}
	}

	@Test
	void readsWithinBudgetAndRejectsOversizedValues() throws Exception {
		try (DataStore store = new DataStore(directory, "values")) {
			byte[] value = new byte[] { 1, 2, 3 };
			int id = store.storeData(value);
			assertThat(store.getData(id, value.length)).containsExactly(value);
			assertThatThrownBy(() -> store.getData(id, value.length - 1))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("read budget");
			assertThat(store.getData(id + 1, value.length)).isNull();
			assertThatThrownBy(() -> store.getData(id, -1)).isInstanceOf(IllegalArgumentException.class);
		}
	}

	@Test
	void rejectsCorruptOffsetsAndLengthsBeforeBoundedRead() throws Exception {
		try (DataStore store = new DataStore(directory, "values")) {
			int id = store.storeData(new byte[] { 1, 2, 3 });
			store.sync();
			try (RandomAccessFile ids = new RandomAccessFile(new File(directory, "values.id"), "rw");
					RandomAccessFile data = new RandomAccessFile(new File(directory, "values.dat"), "rw")) {
				ids.seek((long) id * Long.BYTES);
				long originalOffset = ids.readLong();
				for (long offset : new long[] { -1, 1, Long.MAX_VALUE }) {
					ids.seek((long) id * Long.BYTES);
					ids.writeLong(offset);
					assertThatThrownBy(() -> store.getData(id, 16)).isInstanceOf(IOException.class);
				}
				ids.seek((long) id * Long.BYTES);
				ids.writeLong(originalOffset);
				for (int length : new int[] { -1, 4, Integer.MAX_VALUE }) {
					data.seek(originalOffset);
					data.writeInt(length);
					assertThatThrownBy(() -> store.getData(id, 16)).isInstanceOf(IOException.class);
				}
			}
		}
	}

	@Test
	void rejectsCorruptLengthsBeforeAllocatingPayload() throws Exception {
		try (DataStore store = new DataStore(directory, "values")) {
			int id = store.storeData(new byte[] { 1, 2, 3 });
			store.sync();
			try (IDFile ids = new IDFile(new File(directory, "values.id"));
					RandomAccessFile data = new RandomAccessFile(new File(directory, "values.dat"), "rw")) {
				long offset = ids.getOffsetNoCache(id);
				for (int length : new int[] { 0, -1, 4, Integer.MAX_VALUE }) {
					data.seek(offset);
					data.writeInt(length);
					assertThat(store.hasData(id)).as("length %s", length).isFalse();
				}
			}
		}
	}

	@Test
	void rejectsInvalidOffsetsWithoutOverflow() throws Exception {
		try (DataStore store = new DataStore(directory, "values")) {
			int id = store.storeData(new byte[] { 1, 2, 3 });
			store.sync();
			try (RandomAccessFile ids = new RandomAccessFile(new File(directory, "values.id"), "rw")) {
				for (long offset : new long[] { 0, -1, 1, Long.MAX_VALUE }) {
					ids.seek((long) id * Long.BYTES);
					ids.writeLong(offset);
					assertThat(store.hasData(id)).as("offset %s", offset).isFalse();
				}
			}
		}
	}

	@Test
	void recognizesLargeSparseValueFromItsHeaderOnly() throws Exception {
		long offset;
		int id;
		try (DataStore store = new DataStore(directory, "values")) {
			id = store.storeData(new byte[] { 1 });
			store.sync();
			try (IDFile ids = new IDFile(new File(directory, "values.id"))) {
				offset = ids.getOffsetNoCache(id);
			}
		}
		int length = 128 * 1024 * 1024;
		try (RandomAccessFile data = new RandomAccessFile(new File(directory, "values.dat"), "rw")) {
			data.seek(offset);
			data.writeInt(length);
			data.setLength(offset + Integer.BYTES + length);
		}
		try (DataStore store = new DataStore(directory, "values")) {
			assertThat(store.hasData(id)).isTrue();
			assertThatThrownBy(() -> store.getData(id, 4096))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("read budget");
		}
	}
}
